// Generated by AI, edited by humans

function setupPageTransitions(): void {
    document.addEventListener('click', (event) => {
        // Only primary mouse click without modifiers (Ctrl/Cmd, Shift, Alt)
        if (event.button !== 0 || event.ctrlKey || event.metaKey || event.shiftKey || event.altKey) {
            return;
        }

        const link = (event.target as HTMLElement).closest('a');
        if (!link) {
            return;
        }

        const href = link.getAttribute('href');
        const target = link.getAttribute('target');

        // Ignore hash anchors, protocols, downloads, or external links
        if (!href || href.startsWith('#') || href.includes('://') || href.startsWith('mailto:') || target === '_blank') {
            return;
        }

        const destinationUrl = new URL(link.href, window.location.href);
        if (destinationUrl.origin !== window.location.origin) {
            return;
        }

        // Avoid animating if clicking on current page url with same path
        if (destinationUrl.pathname === window.location.pathname && destinationUrl.search === window.location.search) {
            return;
        }

        document.body.classList.remove('shown');
    });

    // In case user navigates back using browser history cache (bfcache)
    window.addEventListener('pageshow', (event) => {
        if (event.persisted) {
            document.body.classList.add('shown');
        }
    });
}

export function waitForPageReady(additionalReadyPromise?: Promise<unknown>): void {
    setupPageTransitions();

    const domReady = new Promise<void>((resolve) => {
        if (document.readyState === 'interactive' || document.readyState === 'complete') {
            resolve();
            return;
        }
        document.addEventListener('DOMContentLoaded', () => resolve(), { once: true });
    });

    const waitList: Promise<unknown>[] = [domReady];

    if ('fonts' in document) {
        waitList.push(document.fonts.ready);
    }

    if (additionalReadyPromise) {
        waitList.push(additionalReadyPromise);
    }

    Promise.all(waitList).then(() => {
        document.body.classList.add('shown');
    });
}
